    for (p,e),v in coeff.items():
        ans+=v*2**p*_cross_pseudo((parts[0]-e,)+parts[1:],p)
    ans-=Fraction(sum(parts[i]*parts[j] for i in range(len(parts)) for j in range(i)),2)
    assert ans.denominator==1
    return int(ans)

